/// <summary>
/// An extension class for GUPPriceRebatePriceAttributeGroupEdit form's GUPPricingRuleConditionCopy data source.
/// </summary>
[ExtensionOf(FormDataSourceStr(GUPPriceRebatePriceAttributeGroupEdit, GUPPricingRuleConditionCopyLine))]
internal final class METGUPPriceRebatePriceAttributeGroupEditFormGUPPRCCopyLineDS_Extension
{
}

Method.Source:
/// <summary>
///  Method to edit the pricing rule condition value, based on whether external sales data is used and if the attribute is linked to SalesTable or SalesLine.
/// </summary>
/// <param name = "_set">Boolean value that determines a value has been set</param>
/// <param name = "_ruleCondition">Active buffer of GUPPricingRuleConditionCopy table</param>
/// <param name = "_text">Actual value entered</param>
/// <returns>Value entered or a original value based on external sales data check</returns>
public edit GUPAttributeValue editPricingRuleConditionValue(boolean _set, GUPPricingRuleConditionCopy _ruleCondition, GUPAttributeValue _text)
{
    if (_set 
        && !this.isAttributeOfSalesTableOrSalesLineValidation(_ruleCondition)
        && _text != '')
    {
        // External sales data is used, and the attribute is linked to SalesTable or SalesLine.
        // Therefore, we cannot allow setting a value for this attribute beloging to SalesTable or SalesLine.
        // And to prevent the update occuring the base call, we set _set to false, which then actually fetches back the existing or original value, a blnak value.
        _set = false;
        checkFailed("@MET:METExternalSalesDataSOError");
    }

    return next editPricingRuleConditionValue(_set, _ruleCondition, _text);
}

/// <summary>
/// Method to determine if the attribute is linked to SalesTable or SalesLine when external sales data is used.
/// </summary>
/// <param name = "_ruleCondition">Active buffer of GUPPricingRuleConditionCopy table</param>
/// <returns>A boolean true, if attribute is not part of SalesTable or SalesLine, else false</returns>
private boolean isAttributeOfSalesTableOrSalesLineValidation(GUPPricingRuleConditionCopy _ruleCondition)//,GUPAttributeValue _text)
{
    TAMRebateTable  rebateTable = this.formRun().dataSource(formDataSourceStr(GUPPriceRebatePriceAttributeGroupEdit,TAMRebateTable )).cursor();
    TAMRebateDeal   rebateDeal;

    select firstonly METUseExternalSellData from rebateDeal
        where rebateDeal.RecId == rebateTable.RebateDeal;

    if (rebateDeal.METUseExternalSellData == NoYes::Yes && rebateTable.PriceComponentCombination)
    {
        GUPPricingAttributeLink priceAttributeLink = _ruleCondition.priceAttributeLink();
        if ((priceAttributeLink.TableName == tableStr(SalesTable) || priceAttributeLink.TableName == tableStr(SalesLine)))
        {
            return false;
        }
    }

    return true;
}
